#include "LaunchFailure.hpp"
#include <iostream>
using namespace udm;
int wmain(int argc,wchar_t** argv){if(argc!=2)return 2;const auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json checks=Json::array();std::string failure;const auto check=[&](bool ok,const char* name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);};
 try{
  for(const auto& args:std::vector<std::vector<std::wstring>>{{},{L"/n"},{L"--silent"},{L"/d",L"https://example.test/video",L"/n"},{L"--silent",L"--paused"},{L"--background",L"--silent"},{L"--name",L"/n"},{L"--name",L"--silent"},{L"--name",L"--silent",L"/n"},{L"--instance-tag",L"valid-tag_32",L"/n"}}){auto options=parseLaunch(args);check(launchSilentFailureRequested(args)==options.silent,"The early error hint agrees with successful command parsing");}
  for(const std::wstring arg:{L"--data-dir",L"--instance-tag",L"--wait-process",L"--add",L"/d",L"--shortcut",L"/u",L"--folder",L"/p",L"--name",L"/f"}){check(!launchSilentFailureRequested({arg,L"/n"})&&!launchSilentFailureRequested({arg,L"--silent"}),"A value-taking option does not mistake its value for quiet mode");check(launchSilentFailureRequested({arg,L"/n",L"--silent"}),"An actual later quiet switch still controls error presentation");}
  for(const auto& args:std::vector<std::vector<std::wstring>>{{L"/n",L"--folder"},{L"--unknown",L"/n"},{L"--silent",L"--wait-process",L"oops"},{L"--instance-tag",std::wstring(33,L'a'),L"/n"}}){bool rejected=false;try{parseLaunch(args);}catch(const std::exception&){rejected=true;}check(rejected&&launchSilentFailureRequested(args),"A malformed silent request retains its noninteractive error intent");}
  for(const std::wstring value:{std::wstring(32,L'a'),std::wstring(L"a_A-09"),std::wstring()})check(parseLaunch({L"--instance-tag",value}).tag==utf8(value),"Supported and empty default-context tags preserve their existing behavior");
  for(const std::wstring value:{std::wstring(33,L'a'),std::wstring(L"a b"),std::wstring(L"a/b"),std::wstring(L"a.b"),std::wstring(L"a\nb")}){bool rejected=false;try{parseLaunch({L"--instance-tag",value});}catch(const std::exception& error){rejected=std::string(error.what()).find("Invalid instance tag")!=std::string::npos;}check(rejected,"An unsupported instance tag fails during launch parsing before opening a catalog");}
  const auto saved=GetStdHandle(STD_ERROR_HANDLE);struct Restore{HANDLE handle;~Restore(){SetStdHandle(STD_ERROR_HANDLE,handle);}} restore{saved};Handle output(CreateFileW((root/L"stderr.txt").c_str(),GENERIC_WRITE,FILE_SHARE_READ,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr));if(!output)throw std::runtime_error("Owned error output creation failed");SetStdHandle(STD_ERROR_HANDLE,output.h);check(writeLaunchFailure("Owned silent failure"),"A GUI process can report a launch failure to an inherited writable error handle");SetStdHandle(STD_ERROR_HANDLE,saved);const auto closed=CloseHandle(output.h);output.h=INVALID_HANDLE_VALUE;check(closed!=FALSE,"The owned redirected error handle closes cleanly");check(readText(root/L"stderr.txt")=="UDM: Owned silent failure\r\n","The redirected diagnostic has a stable prefix and complete line terminator");
  SetStdHandle(STD_ERROR_HANDLE,nullptr);check(!writeLaunchFailure("No error handle"),"A missing error handle does not replace a silent failure with a window or throw");SetStdHandle(STD_ERROR_HANDLE,INVALID_HANDLE_VALUE);check(!writeLaunchFailure("Invalid error handle"),"An invalid error handle is handled without throwing");SetStdHandle(STD_ERROR_HANDLE,saved);
 }catch(const std::exception& error){failure=error.what();}atomicText(root/L"results.json",Json{{"passed",failure.empty()},{"checks",checks},{"error",failure}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<(failure.empty()?"passed":failure)<<"\n";return failure.empty()?0:1;}
